#!/usr/bin/env python3
"""Build VERDICTS.md + verdicts.csv for the Parts Velocity + Technician Utilization VIU batch.

Every one of the 131 active cases gets ONE definite verdict from:
  VIU-Observed-PASS | DEVIATION | NOT-BUILT | EXTERNAL-DEPENDENCY
plus a verdict for all SEVEN fields (title, preconditions, steps, expected, references, section, notes).
Read-only: reads the case bodies + the TestRail id-map, writes only into this batch folder.
"""
import csv, json, glob, os, sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..', '..', '..'))
BATCH = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
IDMAP = os.path.join(ROOT, 'build', 'report-suite', 'testrail-id-map.csv')
CASES = os.path.join(ROOT, 'build', 'report-suite', 'cases')
LINK = 'https://shopview.testrail.io/index.php?/cases/view/{}'
BUILD = 'v3.4.1-0ed4433'

idmap = {r['internal_id']: r for r in csv.DictReader(open(IDMAP))}
bodies = {}
for f in sorted(glob.glob(os.path.join(CASES, 'cases-pv-*.json'))) + sorted(glob.glob(os.path.join(CASES, 'cases-tu-*.json'))):
    for c in json.load(open(f)):
        bodies[c['id']] = c

# ---------------------------------------------------------------- verdict table
# v      = overall verdict
# fields = dict of the non-default field verdicts (default OK; notes always EDIT)
# ev     = evidence path(s), relative to this batch folder
# what   = what was observed live
# rc     = the re-check obligation when the build settles
P = 'VIU-Observed-PASS'; D = 'DEVIATION'; NB = 'NOT-BUILT'; EX = 'EXTERNAL-DEPENDENCY'
T = []          # rows appended in report order
def row(cid, v, what, ev, rc, **fields): T.append((cid, v, what, ev, rc, fields))

E_PVUI  = 'evidence/pv/ui/pv-ui-1.json, pv-ui-2.json, pv-ui-3.json, pv-ui-4.json'
E_PVEXP = 'evidence/pv/exports/'
E_CALC  = 'evidence/pv/calc-checks.json'
E_XTRA  = 'evidence/pv/extra-checks.json'
E_GAP   = 'evidence/pv/last-gaps.json'
E_PERM  = 'evidence/perms/permission-matrix.json, singleloc-and-noreports.json, singleloc-pv-tu.json'
E_FIN   = 'evidence/final/final-ui.json'
E_TUUI  = 'evidence/tu/ui/tu-ui-1.json, tu-ui-2.json, tu-ui-3.json, tu-coltoggle.json'
E_TUEXP = 'evidence/tu/exports/'
E_UNR   = 'evidence/tu/unrated/unrated-location.json'
E_CORE  = 'evidence/pv/core-exclusion-final.json, core-exclusion-iscore.json'
RC_STD  = 'Re-run this observation when the branch is declared final or the app-version marker changes.'

# ================================================== PARTS VELOCITY (71)
row('PV-NAV-01', P, 'Reports side-nav shows a PARTS group heading containing "Parts Velocity" and "Inventory Value"; route /reports/parts-velocity opens with page title "Parts Velocity" and tab title "Parts Velocity - Report | ShopView".',
    'evidence/pv/ui/pv-ui-1.json; ../evidence/nav-map.json', RC_STD)
row('PV-NAV-02', P, 'With the saved view cleared the report opens on This Year, Type Both, the 14 default columns, Demand descending, and fetches data automatically (two GETs: one before and one after the saved location set is restored).', E_FIN, RC_STD)
row('PV-NAV-03', P, 'One spinner element is present in the report area during the initial load and the previous rows are still in the DOM until the new data returns.', E_FIN, RC_STD)
row('PV-PERM-01', P, 'Admin (holds reportsPageAccess) gets HTTP 200 on both the data endpoint and the CSV export. reportsPageAccess is the ONLY report atom in the whole FE-permission catalogue, so there is no second permission to hold.', E_PERM, RC_STD)
row('PV-PERM-02', P, 'A Foreman (no reportsPageAccess) sees no Reports entry at all and both /reports/parts-velocity and /reports/technician-utilization bounce to /workorders; the API returns 403 "Access denied.".', E_PERM, RC_STD)
row('PV-PERM-03', P, 'Ordinary reports access alone opens the report and its export; no per-report atom exists anywhere in the catalogue, so the "reports access without Inventory Reports View" state cannot be constructed on this build.', E_PERM, RC_STD)
row('PV-FILT-01', P, 'Type is a single-select (role=option with aria-selected, exactly one true) offering Both / Inventory / Special Order, defaulting to Both, and each selection re-queries the server (type=special_order).', E_PVUI, RC_STD)
row('PV-FILT-03', D, 'The picker offers NINE presets - Last 12 Months, This Year, Last Year, This Quarter, Last Quarter, This Month, Last Month, This Week, Last Week - plus an inline calendar, a "Range: N days" readout, a Today button and Apply. There is NO "Yesterday" and NO "Custom" item, and "Last 12 Months" is not in the spec list. SPEC S2-R2 (verbatim): "The toolbar provides a date range selector offering exactly these options: Today, Yesterday, This Week, Last Week, This Month, Last Month, This Year, Last Year, This Quarter, Last Quarter, Custom." Read as NOT-BUILT-AS-SPECIFIED in a SHARED date-range component (the same control serves every report), i.e. a product decision, not a Parts-Velocity defect. The "no All Time" half of the case PASSES.', E_PVUI, RC_STD)
row('PV-FILT-04', P, 'The 366-day cap is enforced: a 366-day difference returns 200, 367 returns 400 "Date range cannot exceed 366 days."; a reversed range returns 400 "Invalid start date provided. Must be less than end date."; the calendar supplies the custom start/end. Honest limit: the cap was driven through the API, and the picker was not made to emit an over-cap span from the UI (Apply stays enabled and the readout did not exceed 216 days in this run).', E_XTRA + '; ' + E_PVUI, 'Re-drive the over-cap span from the calendar UI once the branch is final, to confirm the on-screen rejection wording.')
row('PV-FILT-05', P, 'Category applies &categories=<uuid> and Vendor applies &vendors=<uuid>, each re-querying the server; both narrow the result set.', E_PVUI, RC_STD)
row('PV-FILT-06', P, 'The report has its OWN toolbar input, data-test-id input_report_search, placeholder "Search parts" (distinct from the global Ctrl+K bar). "brakeclean" matches part number BRAKECLEAN and "stover locknut" matches by description - case-insensitive, part number OR description, applied server-side via &search=.', E_PVUI, RC_STD)
row('PV-FILT-07', P, 'Category and Vendor arrive in ONE query string together (&categories=...&vendors=...) and the result is the intersection - AND logic.', E_PVUI, RC_STD)
row('PV-FILT-08', P, 'Selecting bin "General Storage" issues &bins=<uuid> and narrows the table to 8 rows, all of type inventory.', E_PVUI + '; ' + E_GAP, RC_STD)
row('PV-FILT-09', P, 'Type = Special Order combined with a Bin filter returns rowsNumber 0, while the same bin with Type Inventory or Both returns 8 rows, all inventory - special-order rows are excluded whenever a bin filter is active.', E_PVEXP + '; ' + E_GAP, RC_STD)
row('PV-FILT-10', D, 'The Location filter IS the rightmost control and IS limited to the accessible locations, but on a FIRST visit it defaults to ALL locations (both workplaces), not to the user\'s currently active location. SPEC S2-R9 (verbatim): "On a first visit it defaults to the user\'s currently active location (the location currently selected in the application\'s global location switcher)." Read as a build defect on the default, small and self-contained; the rest of S2-R9 passes.', E_FIN, RC_STD)
row('PV-FILT-11', P, 'A search with no matches returns 0 rows and the data area shows exactly "Empty bays, endless possibilities. Get Going!".', E_PVUI, RC_STD)
row('PV-FILT-12', P, '106 rows carry a null Vendor with no filter applied; with a Vendor filter active NO null-vendor row survives. A Bin filter leaves only inventory rows (parts with no bin are excluded). Honest limit: no part on this org has a null Category (every part resolves to a real "Uncategorized" category), so the no-category third of the case could not be exercised.', E_GAP, 'Re-check the no-category third once a part with a genuinely unassigned category exists.')
row('PV-FILT-13', D, 'A seeded one-location user (Sales Representative, single workplace, impersonated then restored) STILL SEES the Location filter; its menu offers only "Clear all" and the one location name (the "All locations" entry drops out). The per-row Location column is correctly absent. Our case follows Chris Ward\'s 2026-07-31 Q1=A ruling that the filter should be HIDDEN; PV spec S2-E4 still reads (verbatim) "A user with access to only one location still sees the Location filter with a single selectable location; behavior is unchanged from single-location use." Read as the build following the un-updated spec - a product decision awaiting Chris\'s spec edit, not a bug ticket. NO CASE CHANGE.',
    'evidence/perms/singleloc-pv-tu.json, evidence/perms/singleloc2-parts-velocity.png', RC_STD)
row('PV-FILT-14', D, 'The per-row Location column DOES appear only when more than one location is in scope (present with both locations, absent for a single-location user and for a single-location selection), it is NOT in the 20-column picker, and a merged special-order row shows the literal "Multiple". But it renders SIXTH - after Vendor, before Units Sold - not leftmost before Type, on screen AND in both exports. SPEC S7-R8 (verbatim): "the per-row Location column renders as the leftmost column, before Type". Read as a build defect on placement only; every other assertion of the case passes.',
    E_PVUI + '; ' + E_PVEXP + 'pv-csv-GREASE-multi.csv, pv-pdf-GREASE-multi.txt', RC_STD, f_expected='EDIT')
