# ---------------------------------------------------------------- emit
missing = [c for c in idmap if (c.startswith('PV-') or c.startswith('TU-')) and c not in {r[0] for r in T}]
extra = [r[0] for r in T if r[0] not in idmap]
if missing or extra:
    print('MISSING:', missing); print('EXTRA:', extra); sys.exit(1)

NOTE = ('Observed on QA branch build %s on 2026-08-03/04; the branch was declared NOT FINAL, '
        'so this observation is PROVISIONAL and is queued for re-check.' % BUILD)
rows = []
for cid, v, what, ev, rc, f in T:
    b = bodies[cid]; tc = idmap[cid]['testrail_case_id']
    rows.append({
        'internal_id': cid, 'testrail_case_id': tc, 'testrail_link': LINK.format(tc.lstrip('C')),
        'report': 'Parts Velocity' if cid.startswith('PV-') else 'Technician Utilization',
        'section': idmap[cid]['section'], 'title': b['title'], 'verdict': v,
        'field_title': f.get('f_title', 'OK — accurate, %d chars, consistent with its own expected result' % len(b['title'])),
        'field_preconditions': f.get('f_prec', 'OK — reachable; every precondition was satisfiable on this estate'),
        'field_steps': f.get('f_steps', 'OK — executable in order against the build labels observed this run'),
        'field_expected': f.get('f_expected', 'OK'),
        'field_references': f.get('f_refs', 'OK — ticket + spec anchor, both still present in the current spec'),
        'field_section': f.get('f_section', 'OK — API content is in an API-titled section' if b.get('api_related') else 'OK — UI-only case in a functional section'),
        'field_notes': f.get('f_notes', 'EDIT — add the non-final-build marker'),
        'observed': what, 'evidence': ev, 'recheck_obligation': rc,
        'build_marker': BUILD, 'notes_addition': NOTE,
    })

OUT = BATCH
with open(os.path.join(OUT, 'verdicts.csv'), 'w', newline='') as fh:
    w = csv.DictWriter(fh, fieldnames=list(rows[0].keys())); w.writeheader(); w.writerows(rows)

from collections import Counter
tally = Counter(r['verdict'] for r in rows)
per = {}
for r in rows: per.setdefault(r['report'], Counter())[r['verdict']] += 1
print('TOTAL', len(rows), dict(tally))
for k, v in per.items(): print(' ', k, dict(v))
json.dump({'total': len(rows), 'tally': dict(tally), 'perReport': {k: dict(v) for k, v in per.items()},
           'buildMarker': BUILD}, open(os.path.join(OUT, 'verdict-tally.json'), 'w'), indent=1)
